def generate_level(rng, difficulty):
    """Curriculum: obstacle density ramps from 0 to 30% and start-goal distance grows with difficulty."""
    size = 10
    cells = [(x, y) for x in range(size) for y in range(size)]
    min_dist = 2 + int(6 * difficulty)
    while True:
        start, goal = rng.sample(cells, 2)
        if abs(start[0] - goal[0]) + abs(start[1] - goal[1]) >= min_dist:
            break
    density = 0.3 * difficulty
    walls = [list(c) for c in cells if c not in (start, goal) and rng.random() < density]
    return {"walls": walls, "start": list(start), "goal": list(goal)}
